package android.view;public class ViewPropertyAnimator{public int starts,cancels;public android.animation.TimeInterpolator interpolator;public final java.util.List<android.animation.TimeInterpolator> startedInterpolators=new java.util.ArrayList<>();public float targetAlpha=1,targetX=1,targetY=1,targetTranslation;public ViewPropertyAnimator alpha(float f){targetAlpha=f;return this;}public ViewPropertyAnimator translationY(float f){targetTranslation=f;return this;}public ViewPropertyAnimator scaleX(float f){targetX=f;return this;}public ViewPropertyAnimator scaleY(float f){targetY=f;return this;}public ViewPropertyAnimator setDuration(long ms){return this;}public ViewPropertyAnimator setStartDelay(long ms){return this;}public ViewPropertyAnimator setInterpolator(android.animation.TimeInterpolator i){interpolator=i;return this;}public void start(){starts++;startedInterpolators.add(interpolator);}public void cancel(){cancels++;}}
